import{_ as c,o,c as d,a1 as t}from"./chunks/framework.BKrM4vFX.js";const _=JSON.parse('{"title":"AGENTS.md — правила работы ИИ-агентов с mock-services","description":"AGENTS.md — правила работы ИИ-агентов с mock-services. Инструкция для агентов (Arena Agent Mode, Claude Code и др.), которые меняют этот репозиторий. Всё, что заявлено ниже, проверено по файлам репозитория (package.json, CONTRIBUTING.md, scripts/, .github/workflows/ci.yml); ","frontmatter":{"sourcePath":"AGENTS.md"},"headers":[{"level":1,"title":"AGENTS.md — правила работы ИИ-агентов с mock-services","slug":"agentsmd-правила-работы-ИИ-агентов-с-mock-services","link":"#agentsmd-правила-работы-ИИ-агентов-с-mock-services","children":[{"level":2,"title":"0. Правило конфликтов","slug":"_0-Правило-конфликтов","link":"#_0-Правило-конфликтов","children":[]},{"level":2,"title":"1. Что нельзя ломать","slug":"_1-Что-нельзя-ломать","link":"#_1-Что-нельзя-ломать","children":[]},{"level":2,"title":"2. Обязательные прогоны","slug":"_2-Обязательные-прогоны","link":"#_2-Обязательные-прогоны","children":[]},{"level":2,"title":"3. Структура и где что менять","slug":"_3-Структура-и-где-что-менять","link":"#_3-Структура-и-где-что-менять","children":[]},{"level":2,"title":"4. Формальные требования к файлам","slug":"_4-Формальные-требования-к-файлам","link":"#_4-Формальные-требования-к-файлам","children":[]},{"level":2,"title":"5. Env-переменные: правило пяти мест","slug":"_5-env-переменные-правило-пяти-мест","link":"#_5-env-переменные-правило-пяти-мест","children":[]},{"level":2,"title":"6. Process: ветка, коммит, PR","slug":"_6-process-ветка-коммит-pr","link":"#_6-process-ветка-коммит-pr","children":[]},{"level":2,"title":"7. Чего агент делать не должен","slug":"_7-Чего-агент-делать-не-должен","link":"#_7-Чего-агент-делать-не-должен","children":[]},{"level":2,"title":"8. Специфичные для проекта ловушки (проверено на коде)","slug":"_8-Специфичные-для-проекта-ловушки-проверено-на-коде","link":"#_8-Специфичные-для-проекта-ловушки-проверено-на-коде","children":[]},{"level":2,"title":"9. Что читать перед работой","slug":"_9-Что-читать-перед-работой","link":"#_9-Что-читать-перед-работой","children":[]},{"level":2,"title":"10. Документы вне публичного репозитория","slug":"_10-Документы-вне-публичного-репозитория","link":"#_10-Документы-вне-публичного-репозитория","children":[]}]}],"relativePath":"AGENTS.md","filePath":"AGENTS.md"}'),s={name:"AGENTS.md"};function r(i,e,a,l,n,m){return o(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="agentsmd-правила-работы-ИИ-агентов-с-mock-services" tabindex="-1">AGENTS.md — правила работы ИИ-агентов с mock-services <a class="header-anchor" href="#agentsmd-правила-работы-ИИ-агентов-с-mock-services" aria-label="Permalink to &quot;AGENTS.md — правила работы ИИ-агентов с mock-services&quot;">​</a></h1><nav class="doc-static-toc" aria-label="Оглавление"><p class="doc-static-toc__title">Оглавление</p><ul><li class="doc-static-toc__item doc-static-toc__item--1"><a class="doc-static-toc__link" href="#agentsmd-правила-работы-ИИ-агентов-с-mock-services">AGENTS.md — правила работы ИИ-агентов с mock-services</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_0-Правило-конфликтов">0. Правило конфликтов</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_1-Что-нельзя-ломать">1. Что нельзя ломать</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_2-Обязательные-прогоны">2. Обязательные прогоны</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_3-Структура-и-где-что-менять">3. Структура и где что менять</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_4-Формальные-требования-к-файлам">4. Формальные требования к файлам</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_5-env-переменные-правило-пяти-мест">5. Env-переменные: правило пяти мест</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_6-process-ветка-коммит-pr">6. Process: ветка, коммит, PR</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_7-Чего-агент-делать-не-должен">7. Чего агент делать не должен</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_8-Специфичные-для-проекта-ловушки-проверено-на-коде">8. Специфичные для проекта ловушки (проверено на коде)</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_9-Что-читать-перед-работой">9. Что читать перед работой</a></li><li class="doc-static-toc__item doc-static-toc__item--2"><a class="doc-static-toc__link" href="#_10-Документы-вне-публичного-репозитория">10. Документы вне публичного репозитория</a></li></ul></nav><p>Инструкция для агентов (Arena Agent Mode, Claude Code и др.), которые меняют этот репозиторий. Всё, что заявлено ниже, проверено по файлам репозитория (<code>package.json</code>, <code>CONTRIBUTING.md</code>, <code>scripts/*</code>, <code>.github/workflows/ci.yml</code>); додумывать нельзя — только сверяться с первыми руками.</p><p>Полные правила для людей — <a href="./CONTRIBUTING"><code>CONTRIBUTING.md</code></a>. Планирование доработок и статусы задач — «план доработок» (бриф — во внутреннем репозитории <code>mock-services-docs</code>). Подготовка к глубокому аудиту и карта покрытия — пакет подготовки к аудиту (в <code>mock-services-docs</code>).</p><h2 id="_0-Правило-конфликтов" tabindex="-1">0. Правило конфликтов <a class="header-anchor" href="#_0-Правило-конфликтов" aria-label="Permalink to &quot;0. Правило конфликтов&quot;">​</a></h2><p>Если инструкция в чате противоречит этому файлу или <code>CONTRIBUTING.md</code> — приоритет у файлов репозитория, а расхождение агент обязан записать в описание PR, а не «разрешить сам». Не угадывайте там, где документация противоречива: ставьте <code>[VERIFY]</code>/вопрос.</p><h2 id="_1-Что-нельзя-ломать" tabindex="-1">1. Что нельзя ломать <a class="header-anchor" href="#_1-Что-нельзя-ломать" aria-label="Permalink to &quot;1. Что нельзя ломать&quot;">​</a></h2><ol><li><strong>Zero dependencies.</strong> В <code>package.json</code> нет <code>dependencies</code> и <code>devDependencies</code>. Любая новая зависимость — стоп и вопрос владельцу.</li><li><strong>Протокольное поведение адаптеров</strong> (форматы полей, коды ошибок, подписи, статусы) — не менять, если задача этого прямо не требует. Эталон: <code>protocols/*.json</code> + конспекты провайдеров в приватном репозитории <code>mock-services-docs</code>.</li><li><strong>Обратная совместимость self-hosted:</strong> поведение без <code>MOCK_HOSTED</code>/токенов не меняется; <code>default</code>-песочница и её креды — тоже.</li><li><strong>Никаких реальных секретов, PAN и ПДн</strong> в коде, тестах, логах, примерах и fixtures.</li><li><strong>Историю git и теги не переписывать</strong>, <code>main</code> не пушить напрямую.</li></ol><h2 id="_2-Обязательные-прогоны" tabindex="-1">2. Обязательные прогоны <a class="header-anchor" href="#_2-Обязательные-прогоны" aria-label="Permalink to &quot;2. Обязательные прогоны&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Когда</th><th>Команда</th></tr></thead><tbody><tr><td><strong>до</strong> правок (зафиксировать зелёную базу) и <strong>после</strong> каждого PR</td><td><code>npm test</code></td></tr><tr><td>тронуты <code>protocols/*.json</code>, маршруты/коды/статусы в <code>services/*/server.js</code>, конспекты провайдеров (приватный <code>mock-services-docs</code>)</td><td><code>npm run check:drift</code></td></tr><tr><td>тронуты <code>.md</code> в корне, <code>docs/</code>, <code>services/*/README.md</code>, <code>packages/core/README.md</code></td><td><code>npm run check:links</code></td></tr><tr><td>тронуты <code>index.html</code>, <code>_sidebar.md</code>, <code>site/**</code> или добавлен документ в <code>docs/</code></td><td><code>npm run check:site</code></td></tr><tr><td>тронуты env-переменные, <code>docker-compose*.yml</code>, <code>Dockerfile</code></td><td><code>npm run check:env</code>, <code>npm run test:compose</code> и <code>node scripts/docker-smoke.js</code></td></tr><tr><td><code>npm test</code> = одиннадцать selftest-скриптов (<code>test:core</code> + десять <code>test:&lt;сервис&gt;</code>) +</td><td></td></tr><tr><td><code>check:links</code> + <code>check:site</code> + <code>check:tables</code> + <code>check:env</code> + <code>check:drift</code></td><td></td></tr><tr><td>(<a href="https://github.com/rucorp/mock-services/blob/main/package.json" target="_blank" rel="noreferrer"><code>package.json:8</code></a>).</td><td></td></tr><tr><td><strong><code>test:compose</code> и <code>test:docker</code> в <code>npm test</code> НЕ входят</strong> — их прогоняет job <code>docker</code> в</td><td></td></tr><tr><td>CI (<a href="https://github.com/rucorp/mock-services/blob/main/.github/workflows/ci.yml" target="_blank" rel="noreferrer"><code>.github/workflows/ci.yml:69-184</code></a>); локально они требуют Docker.</td><td></td></tr><tr><td>Отчёт в PR обязан перечислить, какие прогоны выполнены и их финальные строки.</td><td></td></tr></tbody></table><p>Отдельной «документационной» job в CI нет: <code>check:links</code>, <code>check:site</code>, <code>check:tables</code>, <code>check:env</code> и <code>check:drift</code> — шаги внутри job <code>test</code> (<a href="https://github.com/rucorp/mock-services/blob/main/.github/workflows/ci.yml" target="_blank" rel="noreferrer"><code>.github/workflows/ci.yml:58-67</code></a>), то есть битая ссылка или сломанная навигация сайта краснит весь matrix <code>test</code> на трёх версиях Node.</p><p>Тесты: без <code>sleep</code>-ожиданий и без фиксированных портов (<code>:0</code>), новые сценарии — новым пунктом selftest&#39;а соответствующего сервиса, дефекты — регресс-тестом.</p><h2 id="_3-Структура-и-где-что-менять" tabindex="-1">3. Структура и где что менять <a class="header-anchor" href="#_3-Структура-и-где-что-менять" aria-label="Permalink to &quot;3. Структура и где что менять&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Зона</th><th>Файл</th><th>Комментарий</th></tr></thead><tbody><tr><td>Инфраструктура (состояние, песочницы, вебхуки, редакция, SSRF, HTML, часы, сценарии, auth)</td><td><a href="https://github.com/rucorp/mock-services/blob/main/packages/core/index.js" target="_blank" rel="noreferrer"><code>packages/core/index.js</code></a></td><td>50 экспортов; протоколов здесь нет</td></tr><tr><td>Адаптеры (только декларация протокола)</td><td><code>services/&lt;name&gt;-mock/server.js</code></td><td>tbank 3430, kassa 1966, yookassa 2115, atol 1672 строк</td></tr><tr><td>Тесты</td><td><code>services/&lt;name&gt;-mock/selftest.js</code>, <a href="https://github.com/rucorp/mock-services/blob/main/packages/core/selftest.js" target="_blank" rel="noreferrer"><code>packages/core/selftest.js</code></a></td><td>self-contained, поднимают сервер на эфемерном порту</td></tr><tr><td>Манифесты протоколов</td><td><code>protocols/*.json</code></td><td>ЮKасса намеренно без манифеста и OpenAPI — см. <code>services/yookassa-mock/README.md:209</code></td></tr><tr><td>OpenAPI 3.1</td><td><code>docs/openapi/*.openapi.json</code></td><td>3 файла</td></tr><tr><td>Проверки</td><td><code>scripts/*.js</code></td><td><code>check-protocol-drift.js</code>, <code>check-docs-links.js</code>, <code>compose-selftest.js</code>, <code>docker-smoke.js</code></td></tr><tr><td>Контейнеры</td><td><code>Dockerfile</code>, <code>docker-compose.yml</code>, <code>docker-compose.include.yml</code></td><td>include — artifact потребителей, менять осторожно</td></tr><tr><td>Документация продукта</td><td><code>README.md</code>, <code>SECURITY.md</code>, <code>CHANGELOG.md</code>, <code>docs/{overview.md,integration,rfc,reference,openapi}</code></td><td>внутренние документы — в закрытом <code>mock-services-docs</code> (§10)</td></tr><tr><td>Сайт документации (GitHub Pages)</td><td><code>_sidebar.md</code>, <code>site-build/.vitepress/</code>, <code>site-build/scripts/</code></td><td>VitePress генерирует самостоятельные HTML-страницы; build-зависимости изолированы в <code>site-build/</code></td></tr></tbody></table><h2 id="_4-Формальные-требования-к-файлам" tabindex="-1">4. Формальные требования к файлам <a class="header-anchor" href="#_4-Формальные-требования-к-файлам" aria-label="Permalink to &quot;4. Формальные требования к файлам&quot;">​</a></h2><ol><li><strong>SPDX в каждом исходнике.</strong> Первая строка — <code>// © 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0</code>, вторая — <code>// SPDX-License-Identifier: Apache-2.0</code>, затем <code>&#39;use strict&#39;;</code>. Сейчас 17/17 <code>.js</code> соответствуют; новый файл без шапки — дефект.</li><li><strong>Markdown-доки в <code>docs/**</code> и корневые публичные доки</strong> начинаются со стандартной шапки проекта (<code>© 2026 … · все права защищены</code> + «Документ проекта mock-services (оригинал: …)»). Формулировка «все права защищены» — <strong>действующий стандарт владельца</strong>; её изменение — исключительное решение владельца (задача MS-05, <code>[DECISION]</code>). <strong>Агент не «исправляет» шапки по своей инициативе</strong> и не добавляет эту строку в новые служебные файлы, не требуемые стандартом (пример — <code>CONTRIBUTING.md</code>, <code>AGENTS.md</code>).</li><li><strong>Ссылки — только относительные</strong> между доками (их проверяет <code>check:links</code>). Учитывайте область проверки: <code>README.md</code>, <code>CONTRIBUTING.md</code>, <code>SECURITY.md</code>, <code>docs/**</code>, <code>services/**</code>, <code>packages/**</code> (<a href="https://github.com/rucorp/mock-services/blob/main/scripts/check-docs-links.js" target="_blank" rel="noreferrer"><code>scripts/check-docs-links.js:23,54-58</code></a>) — <code>CHANGELOG.md</code> и новые корневые файлы проверяются вручную.</li><li><strong>Стиль:</strong> CommonJS, 2 пробела, одинарные кавычки, комментарии по делу на русском с английскими терминами. Никакого «мусора» из других языков и случайных символов.</li><li><strong>Ссылка на источник истины в каждом спорном месте:</strong> конспект провайдера в приватном <code>mock-services-docs</code> (раздел <code>&lt;provider&gt;/…</code>) с датой сверки; внутренний вывод помечать явным <code>[FORK]</code>/«документированный форк».</li></ol><h2 id="_5-env-переменные-правило-пяти-мест" tabindex="-1">5. Env-переменные: правило пяти мест <a class="header-anchor" href="#_5-env-переменные-правило-пяти-мест" aria-label="Permalink to &quot;5. Env-переменные: правило пяти мест&quot;">​</a></h2><p>Любое изменение/добавление <code>MOCK_*</code> обязано отразиться в: <code>docker-compose.yml</code> → <code>docker-compose.include.yml</code> → <code>services/&lt;name&gt;-mock/README.md</code> (env-таблица) → <code>SECURITY.md</code> (если влияет на модель угроз) → <code>CHANGELOG.md</code>. Исключений нет. Правило проверяется скриптом <code>npm run check:env</code> (<a href="https://github.com/rucorp/mock-services/blob/main/scripts/check-env-parity.js" target="_blank" rel="noreferrer"><code>scripts/check-env-parity.js</code></a>): он сверяет <code>server.js</code> с README сервиса, тремя compose-файлами и <code>SECURITY.md</code>, а также дефолты <code>MOCK_PORT</code> и <code>${VAR:-…}</code>. Незакрытый долг ведётся явно в <code>KNOWN_INCLUDE_DEBT</code> (переменные, которые адаптеры читают, но которые в include не проброшены, — менять include-набор без решения владельца нельзя, §7) и печатается в выводе проверки; новый дрейф валит CI.</p><h2 id="_6-process-ветка-коммит-pr" tabindex="-1">6. Process: ветка, коммит, PR <a class="header-anchor" href="#_6-process-ветка-коммит-pr" aria-label="Permalink to &quot;6. Process: ветка, коммит, PR&quot;">​</a></h2><ol><li>Ветка: <code>arena/&lt;срез&gt;-&lt;тема&gt;</code> (или <code>fix/…</code>, <code>docs/…</code>) → <strong>PR в <code>main</code></strong>. В <code>main</code> не пушить.</li><li>Один PR = одна логически связанная группа задач (волны PR-A…PR-G заданы в брифе, §9).</li><li><strong>В описании PR обязательна строка <code>Closes #&lt;номер issue&gt;</code></strong> — без неё задача не считается принятой (именно так закрываются #8, #12, #15, #22, #33, #37, #43).</li><li>Отчёт в описании PR — по схеме: <strong>что сделано / что НЕ сделано / развилки и вопросы владельцу / риски и что осталось непроверенным / команды прогонов с их выводом.</strong></li><li>Ссылки на конспекты провайдеров (приватный <code>mock-services-docs</code>) и коды ошибок — с указанием раздела доки.</li><li>Если задача <code>[DECISION]</code> — PR готовит <strong>варианты</strong>, а не решение владельца.</li><li>Docs-only правки не трогают поведение сервисов; <code>npm test</code> прогоняется в любом случае.</li></ol><h2 id="_7-Чего-агент-делать-не-должен" tabindex="-1">7. Чего агент делать не должен <a class="header-anchor" href="#_7-Чего-агент-делать-не-должен" aria-label="Permalink to &quot;7. Чего агент делать не должен&quot;">​</a></h2><ul><li>Реализовывать задачи из «будущих волн» без постановки (в том числе MS-правки из брифа).</li><li>Менять <code>docker-compose.include.yml</code> так, чтобы потребители получили другой набор env (это deployment artifact; пин образа — только через <code>MOCK_IMAGE_DIGEST</code>, см. «Обновление базового образа» в <code>CONTRIBUTING.md</code>).</li><li>Отключать/ослаблять тесты, чтобы CI стал зелёным; менять <code>check:drift</code> под новую реализацию.</li><li>Добавлять <code>.html</code>-копии документации провайдеров (юридический риск, см. аудит-преп §2.7).</li><li>Публиковать образы/релизы, менять настройки репозитория, GHCR-пакет, protected branches.</li><li>Писать «проверено / закрыто» без <code>файл:строка</code> и без вывода команды.</li></ul><h2 id="_8-Специфичные-для-проекта-ловушки-проверено-на-коде" tabindex="-1">8. Специфичные для проекта ловушки (проверено на коде) <a class="header-anchor" href="#_8-Специфичные-для-проекта-ловушки-проверено-на-коде" aria-label="Permalink to &quot;8. Специфичные для проекта ловушки (проверено на коде)&quot;">​</a></h2><ul><li><code>MOCK_*</code> разбираются через <code>flagEnabled</code> (boolean) и <code>parseDuration</code>/<code>parseMsOr</code> (числа: пустая строка → fallback, <code>0</code> разрешён). Ручной <code>parseInt(x, 10) || N</code> ломает «выключить нулём» — см. комментарий в <code>services/atol-mock/server.js:109-118</code>.</li><li><code>check:drift</code> сверяет наличие строки в <code>server.js</code> подстрокой: маршрут, упомянутый только в комментарии, будет засчитан как реализованный.</li><li><code>readBody</code> на превышении лимита отвечает 413 и <strong>намеренно дренирует</strong> остаток тела — не «закрывать соединение» без задачи.</li><li>Управляющие токены принимаются из query <strong>только в non-hosted</strong> (MS-06 + хвосты #121/Ф-1…Ф-3): ответ со ссылками на консоль переносит принятый токен в HttpOnly-cookie (<code>core.sessionCookiesFromQuery</code>), <code>Location</code> и HTML токенов не содержат, а в hosted <code>?admin_token=</code>/<code>?operator_token=</code>/<code>?sandbox_token=</code> отклоняются (<code>services/kassa-mock/selftest.js</code>, блок <code>#5 A-20</code> + Ф-1/Ф-3; <code>packages/core/selftest.js</code>, блок <code>#121</code>).</li><li><code>escapeHtml</code> (<code>&quot;</code>, <code>&#39;</code>) обязателен и в атрибутах; HTML собирается конкатенацией — никакой вставки значений интегратора «как есть».</li><li>Состояние per-sandbox: <code>state</code> — Proxy поверх контекста запроса; новый код, читающий <code>state</code> вне <code>sandboxRuntime.run(...)</code>, попадает в <code>default</code>/активную песочницу.</li><li>Время доменных сущностей — только через <code>clock.now()</code>; учтите, что <code>createSandboxRuntime</code> сейчас живёт на wall-clock (аудит-преп §2.4).</li></ul><h2 id="_9-Что-читать-перед-работой" tabindex="-1">9. Что читать перед работой <a class="header-anchor" href="#_9-Что-читать-перед-работой" aria-label="Permalink to &quot;9. Что читать перед работой&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Задача</th><th>Читать</th></tr></thead><tbody><tr><td>любая правка кода</td><td><a href="./CONTRIBUTING"><code>CONTRIBUTING.md</code></a>, внутренняя спека проекта[^spec] §2, §6.2</td></tr><tr><td>безопасность/hosted</td><td><a href="./SECURITY"><code>SECURITY.md</code></a>, <a href="./docs/rfc/RFC-001-multi-tenant-sandboxes"><code>docs/rfc/RFC-001-multi-tenant-sandboxes.md</code></a>, пакет подготовки к аудиту[^audit-prep] §2, §4D</td></tr><tr><td>протокол провайдера</td><td>официальная документация провайдера (URL + дата сверки; конспекты — в приватном mock-services-docs), <code>protocols/&lt;provider&gt;.json</code>, <code>docs/integration/&lt;provider&gt;.md</code></td></tr><tr><td>очередь доработок</td><td>«план доработок» — бриф[^brief] §0.1 (статусы), §9 (волны)</td></tr><tr><td>аудит-партия</td><td>чек-лист аудит-партии[^audit-party]</td></tr></tbody></table><p>Стороннему контрибьютору приватные документы не требуются: публичная часть репозитория самодостаточна (README, гайды «за 10 минут», README сервисов, RFC-001, SECURITY). Сноски на приватные документы — контекст команды мейнтейнеров, к внешнему вкладу они не применяются.</p><h2 id="_10-Документы-вне-публичного-репозитория" tabindex="-1">10. Документы вне публичного репозитория <a class="header-anchor" href="#_10-Документы-вне-публичного-репозитория" aria-label="Permalink to &quot;10. Документы вне публичного репозитория&quot;">​</a></h2><p>Часть проектной документации живёт в закрытом репозитории <code>mock-services-docs</code>: внутренняя спека, бриф доработок, аудиты и чек-листы. Ссылки на такие документы оформляются <strong>сноской</strong> (имя документа без ссылки) — публичная часть репозитория самодостаточна, а сноска объясняет, откуда взят контекст.</p><p>[^spec]: <code>docs/canon/MOCK_SERVICES_SPEC.md</code> — внутренняя спека mock-services (карточки SZ-095/SZ-096, T-038). [^audit-prep]: <code>docs/audit/AUDIT-PREP-2026-10-12.md</code> — пакет подготовки к глубокому аудиту, карта покрытия. [^brief]: <code>docs/briefs/CLAUDE-2026-10-12-agent-brief.md</code> — бриф доработок, статусы MS-01…MS-40 и волны. [^audit-party]: <code>docs/audit/CHECKLIST-audit-party.md</code> — регламент запуска аудит-партии.</p>',30)])])}const k=c(s,[["render",r]]);export{_ as __pageData,k as default};
